A=[]
def D(n,d,t,e,**k): A.append(dict(n=n,d=d,t=t,e=e,**k))
D(8,1,"Admin takeover","Takeover interno de um tenant não gerenciado (viral): **criar uma conta self-service** com um endereço do domínio, **entrar no Microsoft 365 admin center**, responder à mensagem **Become the admin** e comprovar a posse do domínio com um **registro TXT**.",
  order=(["Sign in to the Microsoft 365 admin center.","Create a self-signed user account in the Azure AD tenant.","From the Microsoft 365 admin center, add the domain name.","Respond to the Become the admin message.","From the Microsoft 365 admin center, remove the domain name.","Create a TXT record in the contoso.com DNS zone."],[1,0,3,5]))
D(20,1,"Domínios personalizados","Adicionar o domínio personalizado, criar o registro **TXT** no DNS, verificar o domínio e defini-lo como **primário (padrão)**. O domínio .onmicrosoft.com não pode ser excluído.",
  order=(["Delete the contoso.ommicrosoft.com domain.","Add a custom domain name of contoso.com.","Set the domain to primary.","Create a new TXT record in DNS.","Successfully verify the domain name."],[1,3,4,2]))
D(22,1,"Portais de administração","User1: funções do Entra ID (User administrator, Device Administrators, Identity Governance Administrator) → **Entra admin center**. User2: os role groups Records Management e Quarantine Administrator são do **Exchange admin center** (parte da comunidade aponta o portal Purview). User3: funções do Intune → **Intune (Endpoint Manager) admin center**.",
  match=(["Azure Active Directory admin center","Exchange admin center","Microsoft 365 compliance center","Microsoft Endpoint Manager admin center","SharePoint admin center"],[("User1:",0),("User2:",1),("User3:",3)]), r="duvidosa")
D(29,2,"ID Protection","**Leaked credentials** é uma detecção de risco de **usuário**, tratada pela user risk policy. Navegador suspeito e IP anônimo são detecções de risco de **entrada**, tratadas pela sign-in risk policy.", g=("case","LITWARE"),
  match=(["An authentication method policy","A Conditional Access policy","A sign-in risk policy","A user risk policy"],[("Leaked credentials:",3),("A sign-in from a suspicious browser:",2),("Resources accessed from an anonymous IP address:",2)]), s="dup", dupof=107)
D(41,2,"Conditional Access App Control","Variante da Q100 (com o nome antigo, Cloud App Security).", s="dup", dupof=100)
D(68,4,"Access reviews — funções","Criar access reviews de grupos com menor privilégio (entre as opções): **User administrator**. Ver os relatórios de histórico de todas as revisões: **Security reader** (leitura). O dump marcava Global administrator e Global reader; Global administrator não é menor privilégio.",
  match=(["Global administrator","Global reader","Reports reader","Security operator","Security reader","User administrator"],[("User1:",5),("User2:",4)]), ans_orig=[0,1], r="corrigida")
D(90,3,"Azure RBAC em VMs","As duas são funções do **Azure RBAC**: login nas VMs com conta Entra (Virtual Machine User/Administrator Login) e criação de VMs (Virtual Machine Contributor). Funções do Entra ID não dão permissão sobre recursos do Azure. O dump marcava \"Azure AD built-in roles\" para a segunda.",
  match=(["Azure AD built-in roles","Azure AD managed identities","Azure role-based access control (Azure RBAC)"],[("Ensure that users can sign in to Azure virtual machines by using their Microsoft 365 credentials:",2),("Delegate the ability to create new virtual machines:",2)]), ans_orig=[2,0], r="corrigida")
D(100,2,"Conditional Access App Control","Sequência: publicar (registrar) o App1 no Entra ID, criar a **política de CA** com o controle de sessão *Use Conditional Access App Control*, entrar no app para que ele apareça em **Connected apps** no Defender for Cloud Apps e, por fim, criar a **session policy**. O dump invertia a ordem da política de CA.",
  order=(["Publish App1 in Azure AD.","Create a conditional access policy that has session controls configured.","From Microsoft Defender for Cloud Apps, create a session policy.","From Microsoft Defender for Cloud Apps, modify the Connected apps settings for App1."],[0,1,3,2]), ans_orig=[0,3,2,1], r="corrigida")
D(107,2,"ID Protection","**Leaked credentials** é uma detecção de risco de **usuário** (user risk policy). Navegador suspeito e IP anônimo são detecções de risco de **entrada** (sign-in risk policy). Hoje a Microsoft recomenda configurar as duas como políticas de Conditional Access baseadas em risco.", g=("case","LITWARE"),
  match=(["An authentication method policy","A Conditional Access policy","A sign-in risk policy","A user risk policy"],[("Leaked credentials:",3),("A sign-in from a suspicious browser:",2),("Resources accessed from an anonymous IP address:",2)]))
D(134,2,"Templates de Conditional Access","Os templates de CA incluem **All users** e excluem automaticamente o **usuário que cria a política** (Admin1), para evitar que ele perca o acesso. O dump marcava \"None\" na exclusão.",
  match=(["Admin1","All guest and external users","All users","Directory roles","None"],[("Include:",2),("Exclude:",0)]), ans_orig=[2,4], r="corrigida")
D(157,3,"Microsoft Graph — permissões","Sequência: **registrar o app**, **adicionar a permissão de aplicativo** (Directory.Read.All, pois é um serviço sem usuário) e **conceder admin consent**. Não há consentimento sem permissões configuradas antes. O dump colocava o consentimento antes das permissões.",
  order=(["Add a group claim.","Create an app registration.","Grant admin consent.","Add delegated permissions.","Add app permissions."],[1,4,2]), ans_orig=[1,2,4], r="corrigida")
D(230,2,"Monitoramento do Entra ID","Locais e IPs de entrada: **Sign-in logs**. Alterações em usuários e service principals: **Audit logs**. Recomendações de melhoria de segurança: **Identity Secure Score**.",
  match=(["Audit logs","Identity secure score","Provisioning logs","Sign-in logs"],[("Identify the locations and IP addresses used by Azure AD users to sign in:",3),("Identify changes to Azure AD users or service principals:",0),("Review the Azure AD security settings and identify improvement recommendations:",1)]))
D(258,3,"Managed identities via PowerShell","`Get-AzVM` obtém a VM para habilitar a identidade system-assigned com `Update-AzVM -IdentityType SystemAssigned`. `Get-AzADServicePrincipal` obtém o service principal da identidade para adicioná-lo ao grupo. O script mistura o módulo AzureAD, que foi aposentado (Add-AzureADGroupMember); hoje usaria Microsoft Graph PowerShell. Por isso está como borderline.", s="borderline",
  match=(["Get-AzADGroup","Get-AzADServicePrincipal","Get-AzVM","Update-AzADServicePrincipal","Update-AzVM"],[("$vm = [cmdlet] -ResourceGroupName myResourceGroup -Name vm1",2),("$displayname = [cmdlet] -displayname \"vm1\"",1)]))
D(293,3,"Key Vault RBAC com PIM","O PIM gerencia **funções RBAC**, não access policies. Ler e atualizar segredos: **Key Vault Secrets Officer**. Só ler o conteúdo: **Key Vault Secrets User** (menor privilégio).",
  match=(["The GET Secret Permissions Access Policy permission","The Key Vault Secrets Officer RBAC role","The Key Vault Reader RBAC role","The Key Vault Secrets User RBAC role","The LIST Secret Permissions Access Policy permission","The SET Secret Permissions Access Policy permission"],[("User1:",1),("User2:",3)]))
D(298,1,"Entra Connect — erros de sincronização","Os endereços de e-mail do enunciado foram perdidos no dump (ofuscação \"[email protected]\"), o que torna a questão irrecuperável. Pelo gabarito: User1 sincroniza; User2 gera **AttributeValueMustBeUnique** (proxyAddress duplicado); User3 gera **InvalidSoftMatch** (novo objeto colide com o proxyAddress de outro já sincronizado).", s="out", r="duvidosa",
  match=(["AttributeValueMustBeUnique error occurs.","InvalidSoftMatch error occurs.","ObjectTypeMismatch error occurs.","Successfully synced"],[("User1@contoso.com",3),("User2@contoso.com",0),("User3@contoso.com",1)]))
D(377,2,"Global Secure Access — filtragem web","No Internet Access do Global Secure Access: criar a **web content filtering policy** (bloqueando contoso.com), vinculá-la a um **security profile** e aplicar o perfil aos usuários por uma **política de Conditional Access** (sessão: Use Global Secure Access security profile).",
  order=(["Create an app protection policy.","Create a Conditional Access policy.","Create a remote network.","Configure a security profile.","Create a web content filtering policy."],[4,3,1]))
